const company = $json.company;
const section = $json.section;
const llmResponse = $json.choices?.[0]?.message?.content || '{}';

let parsedResponse;
try {
  parsedResponse = JSON.parse(llmResponse);
} catch (e) {
  parsedResponse = {
    status: 'requires_human',
    findings: llmResponse,
    missing_data: ['LLM response parsing failed'],
    human_tasks: ['Manual review required'],
    confidence_score: 0
  };
}

return {
  json: {
    company: company,
    section: section,
    status: parsedResponse.status || 'requires_human',
    findings: parsedResponse.findings || '',
    missing_data: JSON.stringify(parsedResponse.missing_data || []),
    human_tasks: JSON.stringify(parsedResponse.human_tasks || []),
    confidence_score: parsedResponse.confidence_score || 0
  }
};
